    /**
     * Duplicate an existing LLM prompt under a new name. Copies the latest version's content to create a new prompt at version 1. Useful for forking a prompt or as a way to rename since names are immutable after creation.
     *
     * @mcpTool llma-prompt-duplicate
     *
     * @requiredScopes llm_prompt:write
     */
    llmaPromptDuplicate(
        input: AiObservabilityLlmaPromptDuplicateInput,
        options?: RequestOptions
    ): Promise<AiObservabilityLlmaPromptDuplicateOutput>
    /**
     * Get a specific LLM prompt by name. Requires `prompt_name`, which takes either the prompt's exact name or
     * the `id` UUID from any llma-prompt-list or llma-prompt-get response. Call llma-prompt-list to discover
     * valid names; a guessed name that matches nothing returns a 404.
     * An id identifies the prompt, not the version it came from, so passing a specific version's id still
     * returns the latest version. Pass `version` or `label` to pin one.
     * Uses the cached endpoint for fast retrieval.
     * Pass `label` (e.g. 'production') to fetch the version that label currently points to, or `version` for an
     * exact version number — not both. With neither, the latest version is returned.
     * The response always includes `outline`, a flat list of markdown headings parsed from the prompt — useful
     * as a lightweight table of contents. Pass `content=none` to get the outline without the prompt payload,
     * or `content=preview` for a short `prompt_preview` snippet instead of the full prompt.
     * With full content the response also includes `config`, the JSON object of model parameters or agent
     * configuration stored with the version (null when the version has none).
     * Prompt content can contain `@@@prompt:...@@@` references to other prompts. By default the response is
     * the assembled content with each reference replaced by the referenced prompt's content, and
     * `resolved_references` lists the exact versions spliced in. Pass `resolve=false` to get the raw text
     * with the tags intact — always do this before editing the prompt (see llma-prompt-update).
     *
     * @mcpTool llma-prompt-get
     *
     * @requiredScopes llm_prompt:read
     */
    llmaPromptGet(
        input: AiObservabilityLlmaPromptGetInput,
        options?: RequestOptions
    ): Promise<AiObservabilityLlmaPromptGetOutput>
    /**
     * Remove a label from an LLM prompt. The label stops pointing at any version; recreate it with the set-label tool if needed. Confirm nothing depends on the label before removing it.
     *
     * @mcpTool llma-prompt-label-delete
     *
     * @requiredScopes llm_prompt:write
     */
    llmaPromptLabelDelete(
        input: AiObservabilityLlmaPromptLabelDeleteInput,
        options?: RequestOptions
    ): Promise<AiObservabilityLlmaPromptLabelDeleteOutput>
    /**
     * Point a label (for example 'production') at a specific version of an LLM prompt. A label is a movable pointer to exactly one version: if the label already exists on another version of this prompt, it is moved there. Use labels to mark a version as released ('production', 'staging') or roll back by pointing the label at an earlier version. Label names use lowercase letters, numbers, dots, hyphens and underscores; 'latest' is reserved and numbers-only names are not allowed. Each prompt can have at most 50 labels.
     *
     * @mcpTool llma-prompt-label-set
     *
     * @requiredScopes llm_prompt:write
     */
    llmaPromptLabelSet(
        input: AiObservabilityLlmaPromptLabelSetInput,
        options?: RequestOptions
    ): Promise<AiObservabilityLlmaPromptLabelSetOutput>
    /**
     * List all LLM prompts stored for the current team. Optionally filter by name. Pass `label` (e.g. 'production') to get each prompt at the version that label currently points to; prompts without that label are omitted. Returns paginated prompt summaries. By default, only prompt metadata is returned, not full prompt content. Every result also includes `outline`, a flat list of markdown headings parsed from the prompt — use it as a lightweight table of contents, and pair with `content=none` to keep responses small. With `label` and `content=full`, prompt content is returned with `@@@prompt:...@@@` references resolved and `resolved_references` listing the spliced versions; unlabeled listings return raw content with any reference tags intact.
     *
     * @mcpTool llma-prompt-list
     *
     * @requiredScopes llm_prompt:read
     */
    llmaPromptList(
        input: AiObservabilityLlmaPromptListInput,
        options?: RequestOptions
    ): Promise<AiObservabilityLlmaPromptListOutput>
    /**
     * Publish a new version of an existing LLM prompt by name. Name is immutable after creation.
     * You can either provide the full prompt content via 'prompt', or use 'edits' for incremental
     * find/replace updates. Each edit must have 'old' (text to find, must match exactly once) and
     * 'new' (replacement text). Edits are applied sequentially. Only one of 'prompt' or 'edits'
     * may be provided. 'base_version' is required — call llma-prompt-get first and pass its current
     * version number as 'base_version'; a stale base_version fails with a 409 conflict. Pass
     * 'version_description' with a short note on what changed and why — it is shown in the prompt's
     * version history.
     * Pass 'config' (a JSON object) to set model parameters or agent configuration on the new version.
     * If 'config' is omitted the current version's config is carried forward; pass null to clear it.
     * A config-only publish (no 'prompt' or 'edits') keeps the prompt content unchanged.
     * If the prompt contains `@@@prompt:...@@@` references, fetch it with `resolve=false` first and edit
     * that raw text: the default llma-prompt-get response inlines the referenced prompts, so republishing
     * it replaces the references with flattened copies that stop following label moves. 'edits' written
     * against resolved content also fail to match, because the stored content keeps the tags.
     *
     * @mcpTool llma-prompt-update
     *
     * @requiredScopes llm_prompt:write
     */
    llmaPromptUpdate(
        input: AiObservabilityLlmaPromptUpdateInput,
        options?: RequestOptions
    ): Promise<AiObservabilityLlmaPromptUpdateOutput>
